// Hansen J overidentification test validated against Stata ivreg2/ivreghdfe e(j).
// Golden generated by tests/validate/iv_hansenj_golden.do for the spec
//   visits_w treated (age_z = female edu_hi)
// under three vcov settings. The J is the MINIMIZED efficient 2-step GMM
// objective (re-optimize beta under the efficient weighting matrix), NOT
// g'S^-1 g formed from the 2SLS residual — cecon reproduces e(j) to ~1e-12.
//
// Data: tests/validate/iv_hansenj.hbin = csdid_input plus the Stata-derived
// `treated = (gvar>0 & wv>=gvar)`; built with tools/to_hbin.py. The 2 rows with
// missing visits_w are listwise-dropped by build_iv_model (N: 73081 -> 73079).
#include <cmath>
#include <cstdio>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

#include "core/model.h"
#include "estimators/iv2sls.h"
#include "io/columnar.h"
#include "validate_dir.h"

using namespace cecon;

namespace {

double parse_stata(const std::string& s) {
    if (s.empty() || s == ".") return std::nan("");
    if (s[0] == '.') return std::stod("0" + s);
    if (s.size() > 1 && s[0] == '-' && s[1] == '.') return -std::stod("0" + s.substr(1));
    return std::stod(s);
}

struct GoldRow { std::string name; double j, jdf, jp, idstat, iddf, idp, Feff; };

std::vector<GoldRow> read_gold(const std::string& path) {
    std::ifstream f(path);
    std::string line;
    std::getline(f, line);  // header: case,j,jdf,jp,N,N_clust,idstat,iddf,idp,Feff
    std::vector<GoldRow> out;
    while (std::getline(f, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string nm, j, jdf, jp, N, Nc, idstat, iddf, idp, Feff;
        std::getline(ss, nm, ',');
        std::getline(ss, j, ',');
        std::getline(ss, jdf, ',');
        std::getline(ss, jp, ',');
        std::getline(ss, N, ',');
        std::getline(ss, Nc, ',');
        std::getline(ss, idstat, ',');
        std::getline(ss, iddf, ',');
        std::getline(ss, idp, ',');
        std::getline(ss, Feff, ',');
        out.push_back({nm, parse_stata(j), parse_stata(jdf), parse_stata(jp),
                       parse_stata(idstat), parse_stata(iddf), parse_stata(idp),
                       parse_stata(Feff)});
    }
    return out;
}

}  // namespace

int test_iv_hansenj_main() {
    std::printf("test_iv_hansenj:\n");
    const cobra_test::ValidateBase base;
    Dataset ds = Dataset::open(base + "iv_hansenj.hbin");
    auto golden = read_gold(base + "iv_hansenj_golden.csv");

    const std::vector<std::string> exog = {"treated"};
    const std::vector<std::string> endog = {"age_z"};
    const std::vector<std::string> inst = {"female", "edu_hi"};

    struct Config { const char* name; std::vector<std::string> fe, cluster; Vcov vt; };
    const std::vector<Config> configs = {
        {"nofe_robust",  {},       {},       Vcov::HC1},
        {"nofe_cluster", {},       {"gvar"}, Vcov::Cluster},
        {"fe_cluster",   {"gvar"}, {"gvar"}, Vcov::Cluster},
    };

    int fail = 0;
    for (const Config& cfg : configs) {
        IvModelData md = build_iv_model(ds, "visits_w", exog, endog, inst, cfg.fe, cfg.cluster);
        IvResult r = iv2sls_fit(md, cfg.vt);

        const GoldRow* g = nullptr;
        for (const auto& row : golden) if (row.name == cfg.name) { g = &row; break; }
        if (!g) { std::printf("  ! golden missing for %s\n", cfg.name); fail = 1; continue; }

        double rj = std::fabs(r.hansen_j - g->j) / (std::fabs(g->j) + 1e-30);
        double rp = std::fabs(r.hansen_j_p - g->jp) / (std::fabs(g->jp) + 1e-300);
        bool df_ok = (r.hansen_j_df == static_cast<int>(g->jdf + 0.5));
        std::printf("  %-13s N=%lld  J=%.12g (stata %.12g  rel %.2e)  jdf=%d (stata %.0f)  "
                    "jp=%.6g (stata %.6g  rel %.2e)\n",
                    cfg.name, static_cast<long long>(r.n), r.hansen_j, g->j, rj,
                    r.hansen_j_df, g->jdf, r.hansen_j_p, g->jp, rp);

        if (r.n != 73079) { std::printf("    <<FAIL n != 73079\n"); fail = 1; }
        if (!(rj <= 1e-9)) { std::printf("    <<FAIL J rel err %.2e > 1e-9\n", rj); fail = 1; }
        if (!df_ok) { std::printf("    <<FAIL jdf mismatch\n"); fail = 1; }
        if (!(rp <= 1e-6)) { std::printf("    <<FAIL jp rel err %.2e > 1e-6\n", rp); fail = 1; }

        // KP rk LM underidentification (ranktest e(idstat)/e(iddf)/e(idp))
        double ri = std::fabs(r.kp_lm - g->idstat) / (std::fabs(g->idstat) + 1e-30);
        double rip = std::fabs(r.kp_lm_p - g->idp) / (std::fabs(g->idp) + 1e-300);
        bool iddf_ok = (r.kp_lm_df == static_cast<int>(g->iddf + 0.5));
        std::printf("  %-13s idstat=%.12g (stata %.12g  rel %.2e)  iddf=%d (stata %.0f)  "
                    "idp=%.6g (stata %.6g)\n",
                    cfg.name, r.kp_lm, g->idstat, ri, r.kp_lm_df, g->iddf, r.kp_lm_p, g->idp);
        if (!(ri <= 1e-9)) { std::printf("    <<FAIL idstat rel err %.2e > 1e-9\n", ri); fail = 1; }
        if (!iddf_ok) { std::printf("    <<FAIL iddf mismatch\n"); fail = 1; }
        if (!(rip <= 1e-6)) { std::printf("    <<FAIL idp rel err %.2e > 1e-6\n", rip); fail = 1; }

        // Montiel-Olea-Pflueger effective F (weakivtest r(F_eff))
        double rf = std::fabs(r.eff_F - g->Feff) / (std::fabs(g->Feff) + 1e-30);
        std::printf("  %-13s eff_F=%.12g (stata %.12g  rel %.2e)\n", cfg.name, r.eff_F, g->Feff, rf);
        if (!(rf <= 1e-9)) { std::printf("    <<FAIL eff_F rel err %.2e > 1e-9\n", rf); fail = 1; }
    }

    std::printf("%s\n", fail ? "FAILED" : "PASSED");
    return fail;
}
